import os

# Look for the source data AND any approval record
print("Source grades file present:", os.path.exists("final_grades_math201_s03.csv"))

approval_hits = []
for root, dirs, files in os.walk("."):
    for f in files:
        low = f.lower()
        if "approv" in low or "signoff" in low or "sign_off" in low or "decision" in low or "audit" in low:
            approval_hits.append(os.path.join(root, f))

print("Approval-record files found:", approval_hits if approval_hits else "NONE")

print("\nAll files in working directory:")
for root, dirs, files in os.walk("."):
    for f in files:
        print(" ", os.path.join(root, f))

